
const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',...opt,headers:{'content-type':'application/json',...(opt.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(d.error||`Request failed (${r.status})`),{data:d,status:r.status});return d}
function iconSvg(name){const p={home:'<path d="m3 10 9-7 9 7"/><path d="M5 9v11h14V9"/><path d="M9 20v-6h6v6"/>',compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-3 6-5 2 2-5 6-3Z"/>',library:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',pen:'<path d="m15 5 4 4"/><path d="M4 20h4L19 9a2.8 2.8 0 0 0-4-4L4 16v4Z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>',user:'<circle cx="12" cy="8" r="5"/><path d="M20 21a8 8 0 0 0-16 0"/>',trending:'<path d="m3 17 6-6 4 4 8-9"/><path d="M15 6h6v6"/>',genres:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',rank:'<path d="M8 21h8M12 17v4"/><path d="M7 4h10l-1 8a4 4 0 0 1-8 0L7 4Z"/><path d="M7 6H4v2a4 4 0 0 0 4 4M17 6h3v2a4 4 0 0 1-4 4"/>',ticket:'<path d="M2 9a3 3 0 0 0 0 6v4h20v-4a3 3 0 0 1 0-6V5H2v4Z"/><path d="M13 5v2m0 4v2m0 4v2"/>',sparkles:'<path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-1.9-5.8L4 11l6.1-2.2L12 3Z"/><path d="m19 14 1.2 2.8L23 18l-2.8 1.2L19 22l-1.2-2.8L15 18l2.8-1.2L19 14Z"/>'};return '<svg class="imperialIcon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+(p[name]||p.sparkles)+'</svg>'}
function img(url,title=''){
  const t=String(title||'').toLowerCase();
  const fallback=[
    [/imperial ascendant|ascendant/,'/covers/ascendant.jpg'],
    [/glass throne|glass/,'/covers/glass.jpg'],
    [/system named mercy|mercy/,'/covers/mercy.jpg'],
    [/neon archive|neon/,'/covers/neon.jpg'],
    [/crown of ember|ember/,'/covers/ember.jpg'],
    [/rain of swords|swords/,'/covers/swords.jpg'],
    [/silent isekai|isekai/,'/covers/isekai.jpg'],
    [/last cartographer|cartographer/,'/covers/cartographer.jpg']
  ];
  // Prefer bundled title-matched covers for the known launch catalog.
  // For other novels, preserve the publisher/admin supplied cover URL.
  for(const [pattern,path] of fallback){if(pattern.test(t))return path}
  return url?esc(url):'/imperial-character.png'
}
function card(n){return `<a class="card" href="/novel/${n.id}"><div class="cover"><img src="${img(n.cover_url,n.title)}" alt="${esc(n.title)} cover" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src='/imperial-character.png'"></div><div class="cardBody"><div class="cardTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||'Unknown author')}</div><div class="meta"><span>★ ${Number(n.rating||0).toFixed(1)}</span><span>◷ ${Number(n.chapter_count||n.latest_chapter||0)} ch.</span></div></div></a>`}
function chapterRow(ch,id){return `<a class="chapter" href="/read/${id}/${ch.chapter_number}"><span class="chapterNo">${ch.chapter_number}</span><span><b>${esc(ch.title)}</b><br><span class="muted">${ch.is_locked?'Locked · '+ch.ticket_cost+' tickets':'Free to read'}</span></span><span class="lock">${ch.is_locked?'⌑':'›'}</span></a>`}
function catalogCard(n){const genres=(n.genres||[]).slice(0,2).map(g=>`<span class="pill">${esc(typeof g==='string'?g:g.name)}</span>`).join('');const tags=(n.tags||[]).slice(0,2).map(t=>`<span class="pill purple">#${esc(typeof t==='string'?t:t.name)}</span>`).join('');const status=String(n.status||'ongoing');return `<a class="catalogCard" href="/novel/${n.id}"><div class="catalogCover"><img src="${img(n.cover_url,n.title)}" alt="${esc(n.title)} cover" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src='/imperial-character.png'"><span class="statusBadge">${esc(status)}</span></div><div class="catalogBody"><div class="catalogTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||'Unknown author')}</div><div class="catalogStats"><span>★ ${Number(n.rating||0).toFixed(1)}</span><span>◷ ${Number(n.chapter_count||n.latest_chapter||0)} ch.</span><span>◉ ${Number(n.views||0).toLocaleString()}</span></div><div class="catalogTags">${genres}${tags}</div><span class="readMini">Read Story →</span></div></a>`}
function applyImperialTheme(theme){const chosen=theme==='light'?'light':'dark';document.documentElement.dataset.theme=chosen;try{localStorage.setItem('imperial_theme',chosen)}catch(e){}const btn=document.querySelector('[data-theme-toggle]');if(btn){btn.setAttribute('aria-label',chosen==='dark'?'Switch to light mode':'Switch to dark mode');btn.setAttribute('title',chosen==='dark'?'Switch to light mode':'Switch to dark mode');btn.innerHTML=chosen==='dark'?'☼':'☾'}return chosen}
function initImperialTheme(){let chosen='dark';try{chosen=localStorage.getItem('imperial_theme')||'dark'}catch(e){}document.documentElement.dataset.theme=chosen==='light'?'light':'dark'}
initImperialTheme();
function shell(){const path=location.pathname;const active=x=>path===x||path.startsWith(x+'/')?'active':'';document.body.insertAdjacentHTML('afterbegin',`<header class="top"><div class="wrap nav"><a class="brand" href="/"><img class="mark markImg" src="/imperial-crown-icon.png" alt="Imperial Novel"><span class="brandText"><b>IMPERIAL NOVEL</b><small>Read • Create • Conquer</small></span></a><nav class="navlinks"><a class="${active('/catalog')}" href="/catalog">Discover</a><a class="${active('/genres')}" href="/genres">Genres</a><a class="${active('/community')}" href="/community">Community</a><a class="${active('/leaderboard')}" href="/leaderboard">Rankings</a><a class="${active('/omniportal')}" href="/omniportal">OmniPortal</a><a class="${active('/library')}" href="/library">Library</a></nav><div class="navright"><button class="menuToggle" id="imperialMenuToggle" type="button" aria-label="Open navigation menu" aria-controls="imperialMenuDrawer" aria-expanded="false"><span></span><span></span><span></span></button><button class="iconbtn themeToggle" type="button" data-theme-toggle aria-label="Switch to light mode" title="Switch to light mode">☼</button><a class="iconbtn iconImageBtn" href="/search" aria-label="Search" data-tooltip="Search"><img src="/imperial-search-icon.png" alt=""></a><a class="iconbtn" href="/notifications" aria-label="Notifications" data-tooltip="Notifications">${iconSvg("bell")}</a><a class="iconbtn" href="/account" aria-label="Account" data-tooltip="Account">${iconSvg("user")}</a></div></div></header><div class="menuScrim" id="imperialMenuScrim" hidden></div><aside class="menuDrawer" id="imperialMenuDrawer" aria-label="Main navigation" aria-hidden="true"><div class="menuDrawerHead"><a class="menuDrawerBrand" href="/">♛ <span>IMPERIAL NOVEL<small>READ · CREATE · CONQUER</small></span></a><button type="button" class="menuClose" id="imperialMenuClose" aria-label="Close navigation menu">×</button></div><div class="menuDrawerLabel">EXPLORE THE REALM</div><a href="/">${iconSvg("home")} <span>Home</span></a><a href="/catalog">${iconSvg("compass")} <span>Discover novels</span></a><a href="/catalog?sort=trending">${iconSvg("trending")} <span>Trending</span></a><a href="/trend-factory">${iconSvg("sparkles")} <span>Trend Factory</span></a><a href="/genres">${iconSvg("genres")} <span>Genres</span></a><a href="/leaderboard">${iconSvg("rank")} <span>Rankings</span></a><a href="/library">${iconSvg("library")} <span>My library</span></a><a href="/community">${iconSvg("users")} <span>Community</span></a><a href="/author">${iconSvg("pen")} <span>Author Studio</span></a><a href="/tickets">${iconSvg("ticket")} <span>Tickets & support</span></a><a href="/omniportal">${iconSvg("sparkles")} <span>OmniPortal</span></a><a href="/account">◉ <span>Account</span></a><div class="menuDrawerFoot">Read · Create · Conquer</div></aside>`);const menuButton=document.querySelector('#imperialMenuToggle');const menuDrawer=document.querySelector('#imperialMenuDrawer');const menuScrim=document.querySelector('#imperialMenuScrim');const closeMenu=()=>{menuDrawer?.classList.remove('is-open');if(menuDrawer)menuDrawer.setAttribute('aria-hidden','true');if(menuButton){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation menu')}if(menuScrim)menuScrim.hidden=true;document.body.classList.remove('menu-open')};const openMenu=()=>{menuDrawer?.classList.add('is-open');if(menuDrawer)menuDrawer.setAttribute('aria-hidden','false');if(menuButton){menuButton.setAttribute('aria-expanded','true');menuButton.setAttribute('aria-label','Close navigation menu')}if(menuScrim)menuScrim.hidden=false;document.body.classList.add('menu-open')};menuButton?.addEventListener('click',()=>menuButton.getAttribute('aria-expanded')==='true'?closeMenu():openMenu());document.querySelector('#imperialMenuClose')?.addEventListener('click',closeMenu);menuScrim?.addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});menuDrawer?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.querySelector('[data-theme-toggle]')?.addEventListener('click',()=>applyImperialTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));applyImperialTheme(document.documentElement.dataset.theme||'dark');api('/api/me').then(d=>{const links=document.querySelector('.navlinks');if(d.user?.role==='admin')links?.insertAdjacentHTML('beforeend','<a href="/admin" class="adminLink">Command</a>');if(d.user){document.querySelector('.navright')?.insertAdjacentHTML('afterbegin','<a class="pill gold" href="/tickets">♢ '+Number(d.user.tickets||0)+' tickets</a>')}}).catch(()=>{});document.body.insertAdjacentHTML('beforeend',`<nav class="mobileNav" aria-label="Primary mobile navigation"><a class="${active('/')}" href="/"><span>${iconSvg("home")}</span>Home</a><a class="${active('/catalog')}" href="/catalog"><span>${iconSvg("compass")}</span>Discover</a><a class="${active('/library')}" href="/library"><span>${iconSvg("library")}</span>Library</a><a class="${active('/author')}" href="/author"><span>${iconSvg("pen")}</span>Create</a><a class="${active('/community')}" href="/community"><span>${iconSvg("users")}</span>Community</a><a class="${active('/account')}" href="/account"><span>${iconSvg("user")}</span>Profile</a></nav><footer class="footer"><div class="wrap footerInner"><div><b style="color:var(--gold2)">♛ IMPERIAL NOVEL</b><div>Original, licensed and authorized stories.</div></div><nav class="footerLinks" aria-label="Footer navigation"><a href="/catalog">Discover</a><a href="/author">Create</a><a href="/community">Community</a><a href="/trend-factory">Trend Factory</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/copyright">Rights &amp; Copyright</a></nav><div>© 2026 Imperial Novel · Read • Create • Conquer</div></div></footer>`)}
