async function home(){const root=$('#app');root.innerHTML=`<div class="page homePage"><div class="wrap"><section class="hero imperialHero"><div class="heroAtmosphere" aria-hidden="true"><span class="heroOrbit orbitOne"></span><span class="heroOrbit orbitTwo"></span><span class="heroSigil">♛</span></div><div class="heroInner"><div class="heroOverline"><span class="heroLiveDot"></span> A NEW ERA OF STORY DISCOVERY <span class="heroOverlineRule"></span> IMPERIAL EDITION</div><h1>Worlds beyond<br>the <span>ordinary.</span></h1><p class="heroLead">A living library for readers, authors and world-builders. Discover remarkable stories, shape original worlds, and follow the signals that reveal what readers may love next.</p><div class="actions heroActions"><a class="primary heroPrimary" href="/catalog">Explore the Library <span aria-hidden="true">↗</span></a><a class="secondary heroSecondary" href="/made-for-you">Discover my next story <span aria-hidden="true">✦</span></a></div><div class="heroFoot"><span>READ <b>•</b> CREATE <b>•</b> CONQUER</span><span class="heroFootDivider"></span><span>Original. Authorized. Reader-first.</span></div></div><aside class="heroConsole"><div class="consoleTop"><span class="consoleMark">IN</span><div><small>IMPERIAL INTELLIGENCE</small><b>Discovery Console</b></div><span class="consoleStatus"><i></i> READY</span></div><div class="consoleRule"></div><a class="consoleFeature" href="/trending"><span class="consoleGlyph">↗</span><span><small>01 / MOMENTUM</small><b>Trending signals</b><em>Explore stories gaining attention</em></span><span class="consoleArrow">↗</span></a><a class="consoleFeature" href="/made-for-you"><span class="consoleGlyph">⌘</span><span><small>02 / PERSONAL</small><b>Your next world</b><em>Find a story for your mood</em></span><span class="consoleArrow">↗</span></a><a class="consoleFeature" href="/author"><span class="consoleGlyph">✎</span><span><small>03 / CREATION</small><b>Author Studio</b><em>Turn an idea into a universe</em></span><span class="consoleArrow">↗</span></a><div class="consoleFoot"><span>BLACK SUN PROTOCOL</span><span>ACCESS · OPEN</span></div></aside><div class="heroCornerMark" aria-hidden="true">IN <span>✦</span> 01</div></section><section class="quickGrid"><a class="quickCard" href="/catalog?sort=trending"><span>↗</span><div><b>Trending</b><small>See what is rising.</small></div></a><a class="quickCard" href="/made-for-you"><span>⌘</span><div><b>For You</b><small>Find your next world.</small></div></a><a class="quickCard" href="/library"><span>▤</span><div><b>Your Library</b><small>Keep your place.</small></div></a><a class="quickCard" href="/random"><span>✧</span><div><b>Surprise Me</b><small>Take the unknown route.</small></div></a><a class="quickCard" href="/author"><span>✎</span><div><b>Create</b><small>Build a new universe.</small></div></a><a class="quickCard" href="/omniportal"><span>◎</span><div><b>OmniPortal</b><small>Rights-first discovery.</small></div></a></section><section class="featureDeck"><div class="featureIntro"><div class="eyebrow">MORE THAN A READING APP</div><h2>A story universe<br>that works for you.</h2><p>Discovery, creation, community and responsible intelligence, brought together in one imperial ecosystem.</p></div><a class="featureTile trendTile" href="/trend-factory"><span class="featureNumber">01 / DISCOVER</span><span class="featureIcon">⌁</span><b>Trend Factory</b><p>Track story momentum, inspect metadata signals and discover authors worth inviting. Rights review stays in control.</p><span class="featureAction">Explore trend signals ↗</span></a><a class="featureTile worldTile" href="/omniportal"><span class="featureNumber">02 / CONNECT</span><span class="featureIcon">◉</span><b>OmniPortal</b><p>A rights-first gateway for approved sources, creator attribution and future partner connections.</p><span class="featureAction">Open the portal ↗</span></a><a class="featureTile studioTile" href="/author"><span class="featureNumber">03 / CREATE</span><span class="featureIcon">✳</span><b>World Forge</b><p>Develop characters, story bibles and chapters in a focused author workflow.</p><span class="featureAction">Enter Author Studio ↗</span></a><a class="featureTile communityTile" href="/community"><span class="featureNumber">04 / BELONG</span><span class="featureIcon">⌘</span><b>Reader Constellation</b><p>Explore reader spaces, rankings and community discovery as the catalog grows.</p><span class="featureAction">Find your people ↗</span></a></section><section class="section"><div class="sectionHead"><div><div class="eyebrow">THE IMPERIAL CATALOG</div><h2>Rising through the realm</h2><p>Browse published stories currently available in the catalog.</p></div><a class="ghost" href="/catalog?sort=trending">Explore catalog →</a></div><div id="trend" class="grid homeStoryGrid"><div class="skeletonCard"></div><div class="skeletonCard"></div></div></section><section class="unlockBanner"><div><div class="eyebrow">READ · UNLOCK · CONTINUE</div><h2>Your reading, on your terms.</h2><p>Manage tickets transparently and unlock authorized chapters with clear status and controls.</p></div><a class="primary" href="/tickets">Explore Tickets →</a></section><section class="section"><div class="sectionHead"><div><div class="eyebrow">FRESH FROM THE REALM</div><h2>Recently updated</h2><p>Return to worlds with new chapters and updates.</p></div><a class="ghost" href="/catalog?sort=updated">Browse latest →</a></div><div id="latest" class="grid homeStoryGrid"><div class="skeletonCard"></div><div class="skeletonCard"></div></div></section></div></div>`;const [t,l]=await Promise.all([api('/api/novels?sort=trending&limit=10'),api('/api/novels?sort=updated&limit=10')]);const trendRows=t.results||[], latestRows=l.results||[];const renderHomeStories=(selector,rows,empty)=>{const el=$(selector);el.classList.toggle('singleStory',rows.length===1);el.classList.toggle('multiStory',rows.length>1);el.innerHTML=rows.length?rows.map(card).join():`<div class="empty homeCatalogEmpty" style="grid-column:1/-1">${empty}</div>`};renderHomeStories('#trend',trendRows,'The Imperial catalog is waiting for its first published stories.');renderHomeStories('#latest',latestRows,'No recent updates yet.')}
async function trendFactory(){const root=$('#app');root.innerHTML=pageStart('Trend Factory','A rights-first intelligence desk for spotting momentum in the live Imperial catalog.')+`<section class="trendFactoryHero"><div><div class="eyebrow">SIGNAL → ANALYZE → RIGHTS REVIEW</div><h2>Find the next world<br>before it rises.</h2><p>Explore published catalog signals, compare available reader activity, and plan responsible author discovery. This workspace does not ingest chapter text or bypass rights approval.</p><div class="actions"><a class="primary" href="/catalog?sort=trending">Open live catalog ↗</a><a class="secondary" href="/omniportal">Source permissions</a></div></div><div class="trendSeal"><span>IN</span><b>TF</b><small>METADATA FIRST<br>RIGHTS ALWAYS</small></div></section><section class="trendPipeline"><div class="trendStep active"><span>01</span><b>Signal</b><small>Find momentum</small></div><div class="trendConnector"></div><div class="trendStep"><span>02</span><b>Analyze</b><small>Inspect metadata</small></div><div class="trendConnector"></div><div class="trendStep"><span>03</span><b>Author</b><small>Discover & invite</small></div><div class="trendConnector"></div><div class="trendStep"><span>04</span><b>Rights</b><small>Verify permission</small></div><div class="trendConnector"></div><div class="trendStep"><span>05</span><b>Review</b><small>Human approval</small></div></section><section class="trendControls panel"><div class="trendControlTitle"><div><div class="eyebrow">LIVE CATALOG SIGNALS</div><h2>Explore momentum</h2></div><span class="trendDataTag"><i></i> LIVE CATALOG DATA</span></div><div class="trendControlRow"><label class="trendSearch"><span>⌕</span><input id="tfSearch" type="search" placeholder="Search title, author or description" autocomplete="off"></label><select id="tfSort" aria-label="Sort signals"><option value="trending">Trending order</option><option value="views">Most viewed</option><option value="rating">Highest rating</option><option value="updated">Recently updated</option></select><select id="tfType" aria-label="Filter story type"><option value="">All story types</option><option value="original">Original</option><option value="fanfiction">Fanfiction</option></select><button class="secondary" id="tfReset" type="button">Reset</button></div><div id="tfMeta" class="trendMeta">Loading current catalog signals…</div><div id="tfResults" class="grid trendResults"><div class="skeletonCard"></div><div class="skeletonCard"></div></div></section><section class="trendSafetyGrid"><article class="trendSafetyCard"><span class="trendSafetyIcon">⌕</span><div class="eyebrow">SOURCE INTAKE</div><h3>Metadata before content</h3><p>Start with public catalog metadata, RSS feeds or approved APIs. Chapter-body ingestion remains off by default.</p><a href="/omniportal">Review connected sources ↗</a></article><article class="trendSafetyCard"><span class="trendSafetyIcon">♧</span><div class="eyebrow">AUTHOR DISCOVERY</div><h3>Invite, don’t appropriate</h3><p>Creators should be contacted through permitted channels, with attribution and authorization recorded.</p><a href="/author">Open Author Studio ↗</a></article><article class="trendSafetyCard"><span class="trendSafetyIcon">◇</span><div class="eyebrow">RIGHTS GATE</div><h3>Permission before publishing</h3><p>Only permitted works proceed. Human review remains the final gate.</p><a href="/admin">Open review center ↗</a></article></section><div class="trendFactoryNote"><b>Integrity rule</b><span>Trend signals prioritize research. They are not proof of permission or a guarantee that a work may be republished.</span></div></div></div>`;let all=[];const list=$('#tfResults'),meta=$('#tfMeta');const paint=()=>{const q=$('#tfSearch').value.trim().toLowerCase(),kind=$('#tfType').value,sort=$('#tfSort').value;let rows=all.filter(n=>(!kind||String(n.kind||'').toLowerCase()===kind)&&(!q||[n.title,n.author,n.description,n.alt_titles].some(v=>String(v||'').toLowerCase().includes(q))));if(sort==='views')rows.sort((a,b)=>(Number(b.views)||0)-(Number(a.views)||0));else if(sort==='rating')rows.sort((a,b)=>(Number(b.rating)||0)-(Number(a.rating)||0));else if(sort==='updated')rows.sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||'')));meta.textContent=`Showing ${rows.length} of ${all.length} loaded published catalog titles · Available fields only`;list.innerHTML=rows.length?rows.map(card).join(''):`<div class="empty" style="grid-column:1/-1"><h3>No matching titles</h3><p>Try a broader search or reset the filters.</p></div>`};try{const d=await api('/api/novels?sort=trending&limit=50');all=(d.results||[]).filter(n=>!n.publication_status||n.publication_status==='published');paint();$('#tfSearch').addEventListener('input',paint);$('#tfSort').addEventListener('change',paint);$('#tfType').addEventListener('change',paint);$('#tfReset').addEventListener('click',()=>{$('#tfSearch').value='';$('#tfSort').value='trending';$('#tfType').value='';paint()})}catch(e){meta.textContent='Catalog signals could not be loaded.';list.innerHTML=`<div class="notice" style="grid-column:1/-1">${esc(e.message||'Please try again later.')} <a href="/catalog">Open catalog</a></div>`}}

async function catalog(){const root=$('#app');const qs=new URLSearchParams(location.search);const vals={q:qs.get('q')||'',sort:qs.get('sort')||'updated',status:qs.get('status')||'',genre:qs.get('genre')||'',tag:qs.get('tag')||'',kind:qs.get('kind')||'',language:qs.get('language')||'',min_rating:qs.get('min_rating')||''};root.innerHTML=pageStart('Catalog','Discover stories with powerful filters for genre, tags, status, type, language and reader activity.')+`<section class="catalogTop panel"><form id="cf"><div class="catalogSearch"><div class="search"><span>⌕</span><input name="q" placeholder="Search titles, authors, alternate titles..." value="${esc(vals.q)}"></div></div><div class="filterRow"><div class="filterGroup"><span class="filterLabel">Sort</span><select name="sort"><option value="updated">Recently Updated</option><option value="newest">Newest</option><option value="trending">Trending</option><option value="views">Most Viewed</option><option value="rating">Top Rated</option><option value="chapters">Most Chapters</option></select></div><div class="filterGroup"><span class="filterLabel">Status</span><select name="status"><option value="">Any</option><option value="ongoing">Ongoing</option><option value="completed">Completed</option></select></div><div class="filterGroup"><span class="filterLabel">Type</span><select name="kind"><option value="">All Types</option><option value="original">Original</option><option value="fanfiction">Fanfiction</option></select></div><div class="filterGroup"><span class="filterLabel">Minimum Rating</span><select name="min_rating"><option value="">Any</option><option value="4">4+</option><option value="3">3+</option><option value="2">2+</option></select></div></div><div class="filterRow"><div class="filterGroup"><span class="filterLabel">Genre</span><input name="genre" value="${esc(vals.genre)}" placeholder="genre slug, e.g. fantasy"></div><div class="filterGroup"><span class="filterLabel">Tag</span><input name="tag" value="${esc(vals.tag)}" placeholder="tag slug, e.g. system"></div><div class="filterGroup"><span class="filterLabel">Language</span><input name="language" value="${esc(vals.language)}" placeholder="English"></div></div><div class="actions" style="margin-top:12px"><button class="primary" type="submit">Apply Filters</button><a class="ghost" href="/catalog">Clear</a><a class="ghost" href="/genres">Browse Genres</a><a class="ghost" href="/tags">Browse Tags</a><a class="ghost" href="/search">Advanced Search</a></div></form></section><div class="catalogMeta"><b id="resultCount">Loading catalog...</b></div><div id="cat" class="catalogGrid"></div><div id="pager" class="pager"></div></div></div>`;const form=$('#cf');form.sort.value=vals.sort;form.status.value=vals.status;form.kind.value=vals.kind;form.min_rating.value=vals.min_rating;async function load(page=1){const p=new URLSearchParams();for(const [k,v] of Object.entries(vals))if(v)p.set(k,v);p.set('limit','24');p.set('page',page);const d=await api('/api/novels?'+p);const items=d.results||[];$('#resultCount').textContent=items.length?`Showing ${items.length} ${items.length===1?'story':'stories'} · Page ${d.page}`:'No stories found';$('#cat').innerHTML=items.length?items.map(catalogCard).join(''):`<div class="catalogEmpty" style="grid-column:1/-1"><div class="catalogEmptyIcon">♛</div><h2>No novels matched this selection.</h2><p>Try another title, genre, tag, status, type or rating.</p><div class="catalogEmptyActions"><a class="primary" href="/catalog">Reset Catalog</a><a class="secondary" href="/genres">Browse Genres</a><a class="ghost" href="/tags">Browse Tags</a></div></div>`;const pager=$('#pager');pager.innerHTML='';if(d.page>1){p.set('page',d.page-1);pager.insertAdjacentHTML('beforeend',`<a class="secondary" href="/catalog?${p}">← Previous</a>`)}if(items.length===d.limit){p.set('page',d.page+1);pager.insertAdjacentHTML('beforeend',`<a class="primary" href="/catalog?${p}">Next →</a>`)}}form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);const p=new URLSearchParams();for(const [k,v] of f.entries())if(String(v).trim())p.set(k,String(v).trim());location.href='/catalog?'+p};await load(Number(qs.get('page')||1))}
async function genres(){const root=$('#app');root.innerHTML=pageStart('Genres','Enter a genre and let the catalog narrow the realm for you.')+`<div id="genreGrid" class="grid" style="grid-template-columns:repeat(4,minmax(0,1fr));margin-top:22px"></div></div></div>`;const d=await api('/api/genres');$('#genreGrid').innerHTML=d.map(g=>`<a class="panel" href="/catalog?genre=${encodeURIComponent(g.slug)}"><div style="font-size:24px;color:var(--gold2)">✦</div><h3 style="margin:7px 0">${esc(g.name)}</h3><div class="muted">Explore ${esc(g.name)} stories</div></a>`).join('')}
async function tags(){const root=$('#app');root.innerHTML=pageStart('Tags','Browse story themes and fandom-friendly classifications.')+`<div id="tagGrid" style="display:flex;gap:9px;flex-wrap:wrap;margin-top:24px"></div></div></div>`;const d=await api('/api/tags');$('#tagGrid').innerHTML=d.map(t=>`<a class="pill" href="/catalog?tag=${encodeURIComponent(t.slug)}">#${esc(t.name)}</a>`).join('')}
async function search(){const root=$('#app');const q=new URLSearchParams(location.search).get('q')||'';root.innerHTML=pageStart('Search','Find novels, authors and alternate titles, then refine the results with catalog filters.')+`<div class="panel"><form id="sf" class="toolbar"><div class="search" style="display:flex;flex:1"><span>⌕</span><input name="q" placeholder="Search novels, authors, alternate titles..." value="${esc(q)}"></div><button class="primary">Search</button></form><div class="actions" style="margin-top:12px"><a class="ghost" href="/catalog?sort=trending">Trending</a><a class="ghost" href="/catalog?sort=rating">Top Rated</a><a class="ghost" href="/catalog?status=completed">Completed</a><a class="ghost" href="/catalog?kind=fanfiction">Fanfiction</a></div></div><div id="results" class="grid" style="margin-top:18px"></div></div></div>`;if(q){const d=await api('/api/novels?q='+encodeURIComponent(q)+'&limit=50');$('#results').innerHTML=d.results.length?d.results.map(card).join(''):`<div class="empty" style="grid-column:1/-1">No results for “${esc(q)}”.</div>`}else{$('#results').innerHTML='<div class="empty" style="grid-column:1/-1"><h2>Search the Imperial catalog</h2><p>Enter a title, author or alternate title to begin.</p><a class="primary" href="/catalog?sort=trending">Explore Trending Stories</a></div>'}$('#sf').onsubmit=e=>{e.preventDefault();const term=String(new FormData(e.target).get('q')||'').trim();location.href='/search'+(term?'?q='+encodeURIComponent(term):'')}}
async function novel(){const id=location.pathname.split('/')[2];const n=await api('/api/novels/'+id);const root=$('#app');root.innerHTML=`<div class="page"><div class="wrap"><section class="novelHero"><div class="novelCover"><img src="${img(n.cover_url,n.title)}" alt="${esc(n.title)}"></div><div class="novelInfo"><div class="eyebrow">${esc(n.kind||'Story')} · ${esc(n.status||'ongoing')}</div><h1>${esc(n.title)}</h1><div class="muted">by ${esc(n.author||'Unknown author')}</div><div class="meta">${(n.genres||[]).map(g=>`<span class="pill">${esc(g.name)}</span>`).join('')}${(n.tags||[]).map(t=>`<span class="pill purple">#${esc(t.name)}</span>`).join('')}</div><p>${esc(n.description||'No description yet.')}</p><div class="stats"><div class="stat"><b>${Number(n.views||0).toLocaleString()}</b>Views</div><div class="stat"><b id="novelRating">${Number(n.rating||0).toFixed(1)}</b>Rating</div><div class="stat"><b>${n.chapters.length}</b>Chapters</div><div class="stat"><b>${esc(n.rights_status||'authorized')}</b>Rights</div></div><div class="actions"><a class="primary" href="/read/${id}/${Number(n.bookmark||1)}">${n.bookmark?'Continue Reading':'Start Reading'}</a><button id="libraryBtn" class="secondary">${n.in_library?'✓ In Library':'＋ Add to Library'}</button><button id="follow" class="secondary">${n.following?'♥ Following':'♡ Follow'}</button><button id="share" class="ghost">Share</button></div></div></section><div class="tabs"><a class="active" href="/novel/${id}">Overview</a><a href="/novel/${id}/chapters">Chapters</a><a href="#community">Community</a></div><section class="section"><div class="sectionHead"><div><h2>Chapters</h2><p>${n.chapters.length} chapters in this world.</p></div><a class="ghost" href="/novel/${id}/chapters">View chapter list</a></div><div class="chapterList">${n.chapters.slice(0,20).map(ch=>chapterRow(ch,id)).join('')}</div></section><section id="community" class="section"><div class="sectionHead"><div><h2>Reader Community</h2><p>Rate the novel, join the discussion, and report anything that needs attention.</p></div></div><div class="communityGrid"><div class="panel ratingPanel"><h3>Rate this novel</h3><div id="ratingStars" class="ratingStars" aria-label="Novel rating"></div><div id="ratingSummary" class="muted">Loading rating...</div></div><div class="panel"><h3>Join the discussion</h3><textarea id="commentInput" maxlength="1000" rows="4" placeholder="Share your thoughts about this story..."></textarea><div class="actions" style="margin-top:10px"><button id="postComment" class="primary" type="button">Post Comment</button><span class="muted">Maximum 1,000 characters</span></div></div></div><div id="commentsList" style="margin-top:16px"></div></section></div></div>`;$('#libraryBtn').onclick=async()=>{try{const me=await api('/api/me');if(!me.user){location.href='/login';return}const d=await api('/api/library',{method:'POST',body:JSON.stringify({novel_id:Number(id)})});$('#libraryBtn').textContent=d.in_library?'✓ In Library':'＋ Add to Library'}catch(e){alert(e.message)}};$('#follow').onclick=async()=>{try{const d=await api('/api/follow',{method:'POST',body:JSON.stringify({novel_id:Number(id)})});$('#follow').textContent=d.following?'♥ Following':'♡ Follow'}catch(e){alert(e.message)}};$('#share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('#share').textContent='Copied'}catch{}};$('#postComment').onclick=async()=>{try{const text=String($('#commentInput').value||'').trim();if(!text)return alert('Write a comment first.');await api('/api/comments',{method:'POST',body:JSON.stringify({novel_id:Number(id),body:text})});$('#commentInput').value='';await loadCommunity(id)}catch(e){alert(e.message)}};await loadCommunity(id)}
async function loadCommunity(id){await Promise.all([loadRating(id),loadComments(id)])}
async function loadRating(id){try{const d=await api('/api/rating?novel_id='+id);const box=$('#ratingStars'),sum=$('#ratingSummary');box.innerHTML=[1,2,3,4,5].map(i=>`<button class="ratingStar ${i<=Number(d.user_rating||0)?'selected':''}" data-rating="${i}" type="button">★</button>`).join('');sum.textContent=`${Number(d.average||0).toFixed(1)} / 5 · ${Number(d.count||0)} rating${Number(d.count||0)===1?'':'s'}`;$$('.ratingStar').forEach(b=>b.onclick=async()=>{try{const me=await api('/api/me');if(!me.user){location.href='/login';return}const x=await api('/api/rating',{method:'POST',body:JSON.stringify({novel_id:Number(id),rating:Number(b.dataset.rating)})});$('#novelRating').textContent=Number(x.average||0).toFixed(1);await loadRating(id)}catch(e){alert(e.message)}})}catch(e){$('#ratingSummary').textContent='Rating unavailable'}}
async function loadComments(id){try{const d=await api('/api/comments?novel_id='+id),rows=d||[];const list=$('#commentsList');if(!rows.length){list.innerHTML='<div class="empty">No comments yet. Be the first reader to start the conversation.</div>';return}const render=(c,reply=false)=>`<article class="commentItem ${reply?'commentReply':''}"><div class="commentHead"><b>${esc(c.username)}</b><span class="muted">${esc(c.created_at)}</span></div><p>${esc(c.body)}</p><div class="commentActions"><button class="ghost commentLike" data-id="${c.id}" type="button">♥ ${Number(c.likes||0)}</button><button class="ghost commentReplyBtn" data-id="${c.id}" type="button">Reply</button><button class="ghost commentReport" data-id="${c.id}" type="button">Report</button></div></article>`;const byParent={};rows.forEach(c=>(byParent[c.parent_id||0]??=[]).push(c));list.innerHTML=(byParent[0]||[]).map(c=>render(c)+(byParent[c.id]||[]).map(x=>render(x,true)).join('')).join('');$$('.commentLike').forEach(b=>b.onclick=async()=>{try{const me=await api('/api/me');if(!me.user){location.href='/login';return}const x=await api('/api/comments/like',{method:'POST',body:JSON.stringify({comment_id:Number(b.dataset.id)})});b.textContent=`♥ ${Number(x.likes||0)}`}catch(e){alert(e.message)}});$$('.commentReplyBtn').forEach(b=>b.onclick=()=>{const box=$('#commentInput');box.value='@'+(rows.find(x=>Number(x.id)===Number(b.dataset.id))?.username||'')+' ';box.dataset.replyTo=b.dataset.id;box.focus()});$$('.commentReport').forEach(b=>b.onclick=async()=>{try{const reason=prompt('Why are you reporting this comment?','spam');if(!reason)return;await api('/api/comments/report',{method:'POST',body:JSON.stringify({comment_id:Number(b.dataset.id),reason})});alert('Report submitted for moderation.')}catch(e){alert(e.message)}});const post=$('#postComment');post.onclick=async()=>{try{const text=String($('#commentInput').value||'').trim();if(!text)return alert('Write a comment first.');await api('/api/comments',{method:'POST',body:JSON.stringify({novel_id:Number(id),body:text,parent_id:Number($('#commentInput').dataset.replyTo||0)})});$('#commentInput').value='';delete $('#commentInput').dataset.replyTo;await loadCommunity(id)}catch(e){alert(e.message)}}}catch(e){$('#commentsList').innerHTML='<div class="empty">Community comments are temporarily unavailable.</div>'}}
async function chapters(){const id=location.pathname.split('/')[2];const n=await api('/api/novels/'+id);const root=$('#app');root.innerHTML=pageStart(n.title,'Complete chapter archive')+`<div class="toolbar"><a class="primary" href="/read/${id}/1">Start at Chapter 1</a><button id="batch" class="secondary">Batch Unlock</button></div><div class="chapterList">${n.chapters.map(ch=>chapterRow(ch,id)).join('')}</div></div></div>`;$('#batch').onclick=async()=>{try{const count=Number(prompt('Batch size: 10, 25, 50 or 100','10'));if(![10,25,50,100].includes(count))return;const d=await api('/api/novels/'+id+'/batch-unlock',{method:'POST',body:JSON.stringify({count,start_chapter:1})});alert(`Unlocked ${d.unlocked} chapters for ${d.cost} tickets. Balance: ${d.tickets}`);location.reload()}catch(e){alert(e.message)}}}
async function reader(){
 const parts=location.pathname.split('/');const id=parts[2],num=Math.max(1,Number(parts[3]||1));
 const n=await api('/api/novels/'+id);const ch=n.chapters.find(x=>Number(x.chapter_number)===num);if(!ch){location.href='/novel/'+id+'/chapters';return}
 const d=await api('/api/chapters/'+ch.id);const total=n.chapters.length;
 const stored=Number(localStorage.getItem('readerProgress:'+id)||0);const chapterPct=Math.min(100,Math.max(0,Number.isFinite(stored)&&num===Number(localStorage.getItem('readerProgressChapter:'+id))?stored:0));
 const root=$('#app');
 const chapterList=n.chapters.map(x=>`<a class="readerChapterItem ${Number(x.chapter_number)===num?'current':''}" href="/read/${id}/${Number(x.chapter_number)}"><span>Chapter ${Number(x.chapter_number)}</span><span>${esc(x.title)} ${x.is_locked?'🔒':''}</span></a>`).join('');
 const bookmarked=Number(n.bookmark||0)===num;
 const initialNovelProgress=Math.min(100,Math.round((num/Math.max(total,1))*100));
 root.innerHTML=`<div class="readerPage"><div class="readerBar"><div class="readerBarInner"><a class="readerBack" href="/novel/${id}/chapters">← Chapters</a><div class="readerBook"><b>${esc(n.title)}</b><span>Chapter ${num} of ${total}</span></div><div class="readerTools"><button id="fontDown" class="readerTool" type="button">A−</button><button id="fontUp" class="readerTool" type="button">A+</button><button id="bookmarkBtn" class="readerTool ${bookmarked?'saved':''}" type="button" aria-label="Bookmark chapter">${bookmarked?'★':'☆'}</button><button id="readerThemeBtn" class="readerTool" type="button" aria-label="Cycle reader theme" title="Cycle reader theme">◐</button><button id="chapterMenu" class="readerTool" type="button" aria-expanded="false">☰</button></div></div><div class="readerProgress"><span id="readerProgressBar" style="width:${chapterPct||initialNovelProgress}%"></span></div></div><div id="chapterDrawer" class="chapterDrawer" hidden><div class="chapterDrawerHead"><b>Chapter List</b><button id="closeChapterMenu" class="ghost" type="button">Close</button></div><div class="readerPrefs"><label>Theme<select id="readerThemeSelect"><option value="light">Light</option><option value="dark">Dark</option><option value="midnight">Midnight</option><option value="sepia">Sepia</option><option value="imperial">Imperial</option><option value="cosmic">Cosmic</option></select></label><label>Line spacing<select id="readerLineSelect"><option value="1.65">Compact</option><option value="1.85">Comfort</option><option value="2">Relaxed</option></select></label><label>Text width<select id="readerWidthSelect"><option value="500">Focused</option><option value="600">Standard</option><option value="680">Wide</option></select></label></div><div class="readerChapterList">${chapterList}</div></div><main class="readerMain"><div class="readerMeta"><span class="eyebrow">${esc(n.author||'Imperial Novel')}</span><span class="readerProgressText" id="progressText">${chapterPct?chapterPct:initialNovelProgress}% through chapter · ${initialNovelProgress}% through novel</span></div><article class="readerArticle"><h1>${esc(ch.title)}</h1><div class="readerDivider"></div><div id="readerContent" class="readerContent">${d.unlocked?esc(d.content||'This chapter has no content yet.'): `<div class="readerLock"><div class="lockIcon">⌑</div><div class="eyebrow">Authorized chapter</div><h2>Chapter locked</h2><p>This chapter is available through Imperial Novel's authorized unlock system. Unlock it for your account to continue reading.</p><div class="lockCost"><b>${Number(d.ticket_cost||0).toLocaleString()}</b><span>tickets</span></div><button id="unlock" class="primary" type="button">Unlock Chapter</button><a class="secondary" href="/tickets">Get Tickets</a></div>`}</div><div class="readerActions"><div>${d.previous?`<a class="secondary" href="/read/${id}/${Number(d.previous.chapter_number)}">← Previous</a>`:''}</div><div class="readerChapterJump"><a class="ghost" href="/novel/${id}/chapters">Chapter ${num} / ${total}</a></div><div>${d.next?`<a class="primary" href="/read/${id}/${Number(d.next.chapter_number)}">Next →</a>`:''}</div></div></article><section class="readerFooterCard"><div><div class="eyebrow">Keep reading</div><h3>${d.next?`Next: Chapter ${Number(d.next.chapter_number)}`:'You reached the latest published chapter'}</h3><p>${d.next?'Continue the story when you are ready.':'Check the novel page for updates and related stories.'}</p></div>${d.next?`<a class="primary" href="/read/${id}/${Number(d.next.chapter_number)}">Next Chapter →</a>`:`<a class="secondary" href="/novel/${id}">Novel Overview</a>`}</section></main></div>`;
 let size=Number(localStorage.getItem('readerSize')||18);const content=$('#readerContent');content.style.fontSize=size+'px';
 const readerPage=$('.readerPage'),themeNames=['light','dark','midnight','sepia','imperial','cosmic'];
 const setReaderTheme=theme=>{const chosen=themeNames.includes(theme)?theme:'dark';readerPage.dataset.readerTheme=chosen;localStorage.setItem('imperial_reader_theme',chosen);$('#readerThemeSelect').value=chosen;$('#readerThemeBtn').title='Reader theme: '+chosen;$('#readerThemeBtn').setAttribute('aria-label','Reader theme: '+chosen)};
 setReaderTheme(localStorage.getItem('imperial_reader_theme')||'dark');
 $('#readerThemeBtn').onclick=()=>{const i=themeNames.indexOf(readerPage.dataset.readerTheme);setReaderTheme(themeNames[(i+1)%themeNames.length])};
 const lineSelect=$('#readerLineSelect'),widthSelect=$('#readerWidthSelect');
 lineSelect.value=localStorage.getItem('imperial_reader_line_height')||'1.85';widthSelect.value=localStorage.getItem('imperial_reader_width')||'600';
 const applyReaderPrefs=()=>{content.style.lineHeight=lineSelect.value;content.style.maxWidth=widthSelect.value+'px';localStorage.setItem('imperial_reader_line_height',lineSelect.value);localStorage.setItem('imperial_reader_width',widthSelect.value)};
 $('#readerThemeSelect').onchange=()=>setReaderTheme($('#readerThemeSelect').value);lineSelect.onchange=applyReaderPrefs;widthSelect.onchange=applyReaderPrefs;applyReaderPrefs();
 $('#fontDown').onclick=()=>{size=Math.max(15,size-1);localStorage.setItem('readerSize',size);content.style.fontSize=size+'px'};
 $('#fontUp').onclick=()=>{size=Math.min(30,size+1);localStorage.setItem('readerSize',size);content.style.fontSize=size+'px'};
 const drawer=$('#chapterDrawer');$('#chapterMenu').onclick=()=>{drawer.hidden=!drawer.hidden;$('#chapterMenu').setAttribute('aria-expanded',String(!drawer.hidden))};$('#closeChapterMenu').onclick=()=>{drawer.hidden=true;$('#chapterMenu').setAttribute('aria-expanded','false')};
 $('#bookmarkBtn').onclick=async()=>{try{const me=await api('/api/me');if(me.user){await api('/api/bookmark',{method:'POST',body:JSON.stringify({novel_id:Number(id),chapter_number:num})});const now=!$('#bookmarkBtn').classList.contains('saved');$('#bookmarkBtn').classList.toggle('saved',now);$('#bookmarkBtn').textContent=now?'★':'☆';}else{localStorage.setItem('readerBookmark:'+id,String(num));$('#bookmarkBtn').classList.add('saved');$('#bookmarkBtn').textContent='★'}}catch(e){alert(e.message)}};
 if($('#unlock'))$('#unlock').onclick=async()=>{try{await api('/api/chapters/'+ch.id+'/unlock',{method:'POST'});location.reload()}catch(e){alert(e.message)}};
 if(d.unlocked)api('/api/history',{method:'POST',body:JSON.stringify({novel_id:Number(id),chapter_number:num})}).catch(()=>{});
 if(d.unlocked)api('/api/bookmark',{method:'POST',body:JSON.stringify({novel_id:Number(id),chapter_number:num})}).catch(()=>{});
 const updateProgress=()=>{if(!d.unlocked)return;const doc=document.documentElement,max=Math.max(1,doc.scrollHeight-window.innerHeight),pct=Math.min(100,Math.max(0,Math.round((window.scrollY/max)*100)));localStorage.setItem('readerProgress:'+id,String(pct));localStorage.setItem('readerProgressChapter:'+id,String(num));$('#readerProgressBar').style.width=pct+'%';$('#progressText').textContent=`${pct}% through chapter · ${initialNovelProgress}% through novel`};window.addEventListener('scroll',updateProgress,{passive:true});updateProgress();
 if(d.unlocked&&chapterPct>0)setTimeout(()=>{const max=Math.max(0,document.documentElement.scrollHeight-window.innerHeight);window.scrollTo({top:max*chapterPct/100,behavior:'auto'});updateProgress()},80);
 document.addEventListener('keydown',e=>{const target=e.target;const typing=target&&(/INPUT|TEXTAREA|SELECT/.test(target.tagName)||target.isContentEditable);if(typing)return;if(e.altKey&&e.key==='ArrowRight'&&d.next){e.preventDefault();location.href='/read/'+id+'/'+Number(d.next.chapter_number)}else if(e.altKey&&e.key==='ArrowLeft'&&d.previous){e.preventDefault();location.href='/read/'+id+'/'+Number(d.previous.chapter_number)}else if(e.key==='+'||e.key==='='){e.preventDefault();$('#fontUp').click()}else if(e.key==='-'){e.preventDefault();$('#fontDown').click()}else if(e.key.toLowerCase()==='t'){const i=themeNames.indexOf(readerPage.dataset.readerTheme);setReaderTheme(themeNames[(i+1)%themeNames.length])}});

}
async function authPage(mode){const root=$('#app');const login=mode==='login';root.innerHTML=`<div class="page"><div class="wrap"><div class="form panel"><div class="eyebrow">Imperial Account</div><h2>${login?'Sign in':'Create account'}</h2><p class="muted">${login?'Continue your reading journey.':'Join the Imperial reading realm.'}</p><form id="auth"><div class="field"><label>Email</label><input name="email" type="email" required></div>${!login?`<div class="field"><label>Username</label><input name="username" required></div>`:''}<div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div>${!login?`<div class="field"><label>Confirm Password</label><input name="confirm" type="password" minlength="8" required></div>`:''}<button class="primary" style="width:100%">${login?'Sign In':'Register'}</button></form><div id="authMsg" style="margin-top:12px"></div><p class="muted">${login?`New here? <a href="/register" style="color:var(--gold2)">Create an account</a>`:`Already registered? <a href="/login" style="color:var(--gold2)">Sign in</a>`}</p></div></div></div>`;$('#auth').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{if(!login&&f.get('password')!==f.get('confirm'))throw Error('Passwords do not match');const d=await api('/api/auth/'+(login?'login':'register'),{method:'POST',body:JSON.stringify(Object.fromEntries(f))});$('#authMsg').innerHTML=`<div class="notice">${esc(d.message||'Success')}</div>`;if(login)location.href='/account'}catch(x){$('#authMsg').innerHTML=`<div class="notice">${esc(x.message)}</div>`}}}
async function account(){const root=$('#app');let p;try{p=await api('/api/profile')}catch(e){root.innerHTML=pageStart('Your Account','Sign in to access your library, tickets and requests.')+`<div class="panel" style="margin-top:22px"><a class="primary" href="/login">Sign In</a><a class="secondary" href="/register">Create Account</a></div></div></div>`;return}root.innerHTML=pageStart('Account','Your personal Imperial command room.')+`<div class="accountGrid"><aside class="accountMenu"><a class="active" href="/account">Profile</a><a href="/library">Library</a><a href="/history">History</a><a href="/following">Following</a><a href="/tickets">Tickets</a><a href="/requests">Requests</a><a href="/omniportal">OmniPortal</a><button id="logout" class="ghost" style="width:100%;margin-top:8px">Sign out</button></aside><main><div class="panel"><div class="profileTop"><img class="avatar" src="/imperial-character.png" alt=""><div><h2 style="margin:0">${esc(p.user.username)}</h2><div class="muted">${esc(p.user.email)}</div></div></div><div class="metricGrid"><div class="metric"><b>${p.user.tickets}</b><div class="muted">Tickets</div></div><div class="metric"><b>${p.stats.history}</b><div class="muted">Library</div></div><div class="metric"><b>${p.stats.following}</b><div class="muted">Following</div></div><div class="metric"><b>${p.stats.unlocks}</b><div class="muted">Unlocks</div></div></div></div><div class="panel" style="margin-top:15px"><h2>Recommendations</h2><div id="recs" class="grid"></div></div></main></div></div>`;$('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});location.href='/'};try{const r=await api('/api/recommendations');$('#recs').innerHTML=r.map(card).join('')}catch{}}
async function library(mode='library'){const root=$('#app');try{const me=await api('/api/me');if(!me.user){root.innerHTML=pageStart('My Library','Sign in to save stories and sync your reading across devices.')+`<div class="panel"><p>Your library is available after signing in.</p><a class="primary" href="/login">Sign In</a><a class="secondary" href="/register">Create Account</a></div></div></div>`;return}const [items,historyRows,bookmarks,following]=await Promise.all([api('/api/library'),api('/api/history'),api('/api/bookmarks'),api('/api/follows')]);const active=mode==='following'?'following':'library';root.innerHTML=pageStart('My Library','Your saved stories, reading progress and bookmarks, synced to your account.')+`<div class="tabs"><a class="${active==='library'?'active':''}" href="/library">My Library</a><a href="/history">History</a><a class="${active==='following'?'active':''}" href="/following">Following</a></div><section class="section"><div class="sectionHead"><div><h2>Continue Reading</h2><p>Jump back into your most recently read stories.</p></div></div><div class="grid" id="continueList"></div></section><section class="section"><div class="sectionHead"><div><h2>Saved Stories</h2><p>${items.length} novel${items.length===1?'':'s'} in your library.</p></div></div><div class="grid" id="savedList"></div></section><section class="section"><div class="sectionHead"><div><h2>Bookmarked Chapters</h2><p>Your saved chapter positions.</p></div></div><div id="bookmarkList" class="panel"></div></section></div></div>`;const cont=historyRows.slice(0,12);$('#continueList').innerHTML=cont.length?cont.map(x=>`<article class="panel"><div class="muted">${esc(x.author||'Unknown author')}</div><h3>${esc(x.title)}</h3><p>Chapter ${Number(x.chapter_number)}</p><a class="primary" href="/read/${x.novel_id}/${Number(x.chapter_number)}">Continue Reading →</a></article>`).join(''):`<div class="empty" style="grid-column:1/-1">No reading history yet. Open a chapter to begin.</div>`;$('#savedList').innerHTML=items.length?items.map(x=>`<article class="card"><a href="/novel/${x.novel_id}"><div class="cover"><img src="${img(x.cover_url)}" alt="${esc(x.title)} cover" loading="lazy" decoding="async" fetchpriority="low"></div><div class="cardBody"><div class="cardTitle">${esc(x.title)}</div><div class="muted">${esc(x.author||'Unknown author')}</div><div class="meta"><span>★ ${Number(x.rating||0).toFixed(1)}</span><span>${x.latest_chapter?`${Number(x.latest_chapter)} ch.`:'No chapters'}</span></div></div></a><div style="padding:0 13px 13px"><button class="ghost removeLibrary" data-id="${x.novel_id}" type="button">Remove from Library</button></div></article>`).join(''):`<div class="empty" style="grid-column:1/-1">Your library is empty. Open a novel and tap <b>Add to Library</b>.</div>`;$('#bookmarkList').innerHTML=bookmarks.length?bookmarks.map(x=>`<div class="statline"><span><b>${esc(x.title)}</b> · Chapter ${Number(x.chapter_number)}</span><a class="ghost" href="/read/${x.novel_id}/${Number(x.chapter_number)}">Open</a></div>`).join(''):`<div class="empty">No bookmarked chapters yet.</div>`;$$('.removeLibrary').forEach(b=>b.onclick=async()=>{try{await api('/api/library',{method:'POST',body:JSON.stringify({novel_id:Number(b.dataset.id)})});b.closest('.card')?.remove()}catch(e){alert(e.message)}})}catch(e){root.innerHTML=pageStart('My Library')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`}}
