async function tickets(){const root=$('#app');try{const [p,l]=await Promise.all([api('/api/profile'),api('/api/tickets/ledger')]);root.innerHTML=pageStart('Tickets','Your balance and complete ticket ledger.')+`<div class="panel"><div class="metricGrid"><div class="metric"><b>${p.user.tickets}</b><div class="muted">Current balance</div></div><div class="metric"><b>${p.stats.ticketFlow}</b><div class="muted">Net ticket flow</div></div></div><div class="section"><h2 style="font:600 25px Georgia,serif">Ledger</h2><div class="chapterList">${l.length?l.map(x=>`<div class="chapter"><span class="chapterNo">${x.delta>0?'+':''}${x.delta}</span><span><b>${esc(x.reason)}</b><br><span class="muted">${esc(x.created_at)} · ${esc(x.reference||'')}</span></span><span>${x.delta>0?'Credit':'Debit'}</span></div>`).join(''):`<div class="empty">No ticket transactions yet.</div>`}</div></div><div class="notice" style="margin-top:18px">Batch unlock sizes supported: 10, 25, 50 and 100 chapters.</div></div></div>`}catch(e){root.innerHTML=pageStart('Tickets')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`}}
async function requests(){const root=$('#app');let r;try{r=await api('/api/requests')}catch(e){root.innerHTML=pageStart('Request a New Novel','Three free requests each week, then ticket pricing applies.')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`;return}root.innerHTML=pageStart('Request a New Novel','Three free requests each week, then ticket pricing applies.')+`<div class="panel" style="max-width:720px"><div class="stats"><div class="stat"><b>${r.used}/${r.limit}</b>Free requests used</div></div><form id="req"><div class="field"><label>Novel URL</label><input name="url" placeholder="https://example.com/novel/..." required></div><button class="primary">Submit Request</button></form><div id="reqMsg" style="margin-top:12px"></div></div></div></div>`;$('#req').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/requests',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$('#reqMsg').innerHTML=`<div class="notice">${esc(d.message)} Cost: ${d.cost} tickets.</div>`;e.target.reset()}catch(x){$('#reqMsg').innerHTML=`<div class="notice">${esc(x.message)}</div>`}}}
async function omni(){
 const root=$('#app');
 root.innerHTML=pageStart('OmniPortal','Rights-first discovery across Imperial Novel and authorized provider connectors.')+`<div class="panel"><form id="omni" class="toolbar"><div class="search" style="display:flex"><span>✦</span><input name="q" placeholder="Search titles, authors and worlds..."></div><button class="primary">Search</button></form><div class="notice"><b>Legal mode:</b> only authorized connectors are queried. Imports are metadata-only by default. Imperial Novel does not bypass paywalls, DRM, logins or access controls, and does not copy source chapters.</div><div id="omniRes" class="grid" style="margin-top:18px"></div></div></div></div>`;
 $('#omni').onsubmit=async e=>{
  e.preventDefault();
  const q=String(new FormData(e.target).get('q')||'');
  if(q.length<2)return;
  try{
   const d=await api('/api/omni/search?q='+encodeURIComponent(q));
   if(!d.results.length){$('#omniRes').innerHTML='<div class="empty" style="grid-column:1/-1">No authorized results found.</div>';return;}
   $('#omniRes').innerHTML=d.results.map(x=>{
    const ext=String(x.url||'').startsWith('http');
    return `<div class="card"><div class="cardBody"><span class="pill purple">${esc(x.provider)}</span><div class="cardTitle" style="margin-top:10px">${esc(x.title)}</div><div class="muted">${esc(x.author)}</div><p class="muted">${esc(x.description||'')}</p><div class="actions" style="margin-top:12px">${ext?`<a class="ghost" href="${esc(x.url)}" target="_blank" rel="noopener">Open Source</a><button class="secondary omniImport" data-url="${esc(x.url)}">Request Metadata Import</button>`:`<a class="primary" href="${esc(x.url)}">Read on Imperial Novel</a>`}</div></div></div>`;
   }).join('');
   document.querySelectorAll('.omniImport').forEach(btn=>{
    btn.onclick=async()=>{
     try{
      const d=await api('/api/omni/import',{method:'POST',body:JSON.stringify({url:btn.dataset.url})});
      alert(`Metadata import request #${d.job_id} queued. No source chapters will be copied.`);
     }catch(err){alert(err.message)}
    };
   });
  }catch(err){alert(err.message)}
 };
}
