async function authorPublic(){const slug=decodeURIComponent(location.pathname.split('/').pop()||'').trim();const root=$('#app');root.innerHTML=pageStart('Author Profile','Published stories and public catalog activity.')+`<div id="authorProfile" class="panel">Loading author profile...</div></div></div>`;try{const d=await api('/api/novels?author='+encodeURIComponent(slug)+'&limit=50');const rows=d.results||[];if(!rows.length){$('#authorProfile').innerHTML=`<div class="empty"><h2>Author not found</h2><p>No published stories are currently associated with <b>${esc(slug)}</b>.</p><a class="primary" href="/catalog">Browse the Catalog</a></div>`;return}const author=rows[0].author||slug;$('#authorProfile').innerHTML=`<div class="authorHero"><div class="authorAvatar">♛</div><div><div class="eyebrow">PUBLIC AUTHOR</div><h2>${esc(author)}</h2><p>${rows.length} published ${rows.length===1?'story':'stories'} in the Imperial catalog.</p></div></div><div class="section"><div class="sectionHead"><div><h2>Published Stories</h2><p>Explore this author's available works.</p></div></div><div class="grid">${rows.map(card).join('')}</div></div>`}catch(e){$('#authorProfile').innerHTML=`<div class="notice">${esc(e.message||'Unable to load this author profile.')} <a href="/catalog">Return to Catalog</a></div>`}}
function settings(){const root=$('#app');const get=(k,d)=>localStorage.getItem(k)??d;root.innerHTML=pageStart('Settings','Control your Imperial Novel reading and interface experience.')+`<section class="settingsGrid"><div class="panel"><div class="eyebrow">READER</div><h2>Reading Experience</h2><div class="settingRow"><div><b>Font size</b><small>Adjust chapter text size.</small></div><input id="setFont" type="range" min="14" max="26" value="${esc(get('imperial_font_size','18'))}"><output id="fontOut">${esc(get('imperial_font_size','18'))}px</output></div><div class="settingRow"><div><b>Line spacing</b><small>Comfortable reading rhythm.</small></div><select id="setLine"><option value="1.6">Compact</option><option value="1.85">Comfort</option><option value="2">Relaxed</option></select></div><div class="settingRow"><div><b>Reading width</b><small>Choose a narrower or wider text column.</small></div><select id="setWidth"><option value="680">Focused</option><option value="760">Standard</option><option value="860">Wide</option></select></div></div><div class="panel"><div class="eyebrow">MOTION</div><h2>Motion & Accessibility</h2><label class="checkRow"><input id="setReduced" type="checkbox" ${get('imperial_reduced_motion','false')==='true'?'checked':''}><span><b>Reduce motion</b><small>Minimize ambient and interface animations.</small></span></label><label class="checkRow"><input id="setHigh" type="checkbox" ${get('imperial_high_contrast','false')==='true'?'checked':''}><span><b>High contrast</b><small>Increase visual separation for controls and text.</small></span></label></div><div class="panel"><div class="eyebrow">ACCOUNT</div><h2>Account & Privacy</h2><p class="muted">Manage your account, sessions and privacy from your account center.</p><div class="actions"><a class="primary" href="/account">Open Account</a><a class="secondary" href="/notifications">Notifications</a></div></div></section><div id="settingsSaved" class="notice" hidden>Settings saved.</div></div></div>`;const line=get('imperial_line_height','1.85'),width=get('imperial_reader_width','760');$('#setLine').value=line;$('#setWidth').value=width;const save=()=>{localStorage.setItem('imperial_font_size',$('#setFont').value);localStorage.setItem('imperial_line_height',$('#setLine').value);localStorage.setItem('imperial_reader_width',$('#setWidth').value);localStorage.setItem('imperial_reduced_motion',$('#setReduced').checked);localStorage.setItem('imperial_high_contrast',$('#setHigh').checked);$('#fontOut').textContent=$('#setFont').value+'px';document.documentElement.dataset.reducedMotion=$('#setReduced').checked?'true':'false';$('#settingsSaved').hidden=false;clearTimeout(window.__settingsTimer);window.__settingsTimer=setTimeout(()=>$('#settingsSaved').hidden=true,1600)};['#setFont','#setLine','#setWidth','#setReduced','#setHigh'].forEach(x=>$(x)?.addEventListener('input',save));}

async function boot(){shell();const root=document.createElement('main');root.id='app';document.body.insertBefore(root,$('.footer'));try{const p=location.pathname;const titles={'/':'Home','/community':'Community','/leaderboard':'Leaderboard','/tier-list':'Tier List','/random':'Random Novel','/made-for-you':'Made For You','/for-you':'Made For You','/trending':'Trending Now','/vote':'Vote Novels','/notifications':'Notifications','/settings':'Settings','/omniportal':'OmniPortal','/author':'Author Studio','/admin':'Command Center','/trend-factory':'Trend Factory'};if(titles[p])document.title=titles[p]+' | Imperial Novel';if(p==='/')await home();else if(p==='/trend-factory')await trendFactory();else if(p==='/catalog')await catalog();else if(p==='/genres')await genres();else if(p==='/tags')await tags();else if(p==='/search')await search();else if(/^\/novel\/\d+\/chapters\/?$/.test(p))await chapters();else if(/^\/novel\/\d+\/?$/.test(p))await novel();else if(/^\/read\/\d+\/\d+\/?$/.test(p))await reader();else if(p==='/library')await library();else if(p==='/history')await history();else if(p==='/following')await following();else if(p==='/tickets')await tickets();else if(p==='/requests')await requests();else if(p==='/omniportal')await omni();else if(p==='/community')await discoveryPage('community');else if(p==='/leaderboard')await discoveryPage('leaderboard');else if(p==='/tier-list')await discoveryPage('tier-list');else if(p==='/random')await discoveryPage('random');else if(p==='/made-for-you'||p==='/for-you')await discoveryPage('made-for-you');else if(p==='/trending')await discoveryPage('trending');else if(p==='/vote')await discoveryPage('vote');else if(p==='/notifications')await discoveryPage('notifications');else if(p==='/settings')settings();else if(p==='/account')await account();else if(p==='/login')await authPage('login');else if(p==='/register')await authPage('register');else if(p.startsWith('/fandom/')){const slug=p.split('/').pop();location.href='/catalog?tag='+encodeURIComponent(slug)}else if(/^\/author\/[^/]+$/.test(p))await authorPublic();else simplePage('Page not found','The page you requested does not exist.');}catch(e){root.innerHTML=`<div class="page"><div class="wrap"><div class="notice">${esc(e.message||'Something went wrong.')}</div></div></div>`}}
boot();
